public class HeapInspectionDemo {
    public static void main(String[] args) {
        // Programmatically querying JVM memory limits defined by -Xms and -Xmx
        long initialMemoryBytes = Runtime.getRuntime().totalMemory();
        long maxMemoryBytes = Runtime.getRuntime().maxMemory();

        System.out.printf("Initial Heap Size (-Xms): %.2f MB%n", (double) initialMemoryBytes / (1024 * 1024));
        System.out.printf("Maximum Heap Size (-Xmx): %.2f MB%n", (double) maxMemoryBytes / (1024 * 1024));
    }
}
